# ROC对比实验
def plot_auc_curves(tprs):
    mean_fpr = np.linspace(0, 1, 2000)
    plt.plot(mean_fpr, tprs[0], color='#cb0000', alpha=1, linewidth=1.5,  label='AGKformer(AUC=%.4f)' % 0.9732)
    plt.plot(mean_fpr, tprs[1], alpha=0.7, linewidth=1, linestyle='--', label='MDBIRW(AUC=%.4f)' % 0.8956)
    # plt.plot(mean_fpr, tprs[2], alpha=0.4, linestyle='--', label='RCNMF(AUC=%.4f)' % 0.9431)
    plt.plot(mean_fpr, tprs[2], alpha=0.7, linewidth=1,  linestyle='--', label='DWRF(AUC=%.4f)' % 0.9511)
    plt.plot(mean_fpr, tprs[3], alpha=0.7, linewidth=1,  linestyle='--', label='DeepDRM(AUC=%.4f)' % 0.952284573151445)
    plt.plot(mean_fpr, tprs[4], alpha=0.7, linewidth=1,  linestyle='--', label='GCNAT(AUC=%.4f)' % 0.9521)
    plt.plot(mean_fpr, tprs[5], alpha=0.7, linewidth=1,  linestyle='--', label='MDA-AENMF(AUC=%.4f)' % 0.96545153)

    plt.plot([0, 1], [0, 1], linestyle='--', color='black', alpha=0.4)
    plt.xticks(fontsize=10)
    plt.yticks(fontsize=10)
    plt.xlim([-0.05, 1.05])
    plt.ylim([-0.05, 1.05])
    plt.xlabel('False Positive Rate', fontsize=12)
    plt.ylabel('True Positive Rate', fontsize=12)
    # 调整图的尺寸
    plt.gcf().set_size_inches(5, 5)
    # plt.title('ROC curve')
    plt.legend(loc='lower right', fontsize=9.5)
    plt.savefig('Comparative_experiment_ROC_1.pdf', format='pdf', dpi=300, bbox_inches='tight')
    plt.show()
    plt.close()
plot_auc_curves(TPR)

